// Einmaliger Reset 2026-08-01 (6. Verwendung): 4 Vorgaenge hatten contentStage komplett
// leer statt eines gueltigen Wertes - live bis zur Ursache zurueckverfolgt (siehe Commit
// 1600f2b): P3 hatte contentStage korrekt berechnet (watching/needs_content je nach
// empfehlung), P3d's "Verarbeite Eignungs-Entscheidung" hat es aber bei einem Paired-Item-
// Verlust (itemMatching ueber die Execute-Workflow-Grenze) mit einem leeren String
// ueberschrieben - nur bei Zeilen, die zu dem Zeitpunkt sharepicNeedStage='topic_error'
// hatten. Der Bug selbst ist jetzt gefixt; das hier setzt nur die bereits betroffenen 4
// Zeilen auf den empfehlung-passenden Wert zurueck, den P3 damals schon korrekt berechnet
// hatte (verifiziert per historischer Execution 20228 fuer vol_10576).
const TARGETS = [
  { vorgangKey: 'vol_10576', vorgangsnummer: '2026/094', targetStage: 'watching' },
  { vorgangKey: 'vol_10597', vorgangsnummer: '2026/107', targetStage: 'watching' },
  { vorgangKey: 'vol_10582', vorgangsnummer: '2026/099', targetStage: 'needs_content' },
  { vorgangKey: 'vol_10363', vorgangsnummer: '2025/464', targetStage: 'watching' }
];

if (!TARGETS.length) {
  throw new Error('[ContentStage-Reset] TARGETS im Node "Konfiguriere Ziele" befuellen.');
}

// Bewusst NICHT dabei diesmal: headlineChoiceStage/visualPromptStage/judgmentChainProcessedAt -
// die wurden fuer diese 4 Zeilen bereits heute per sharepicNeedStage-Reset korrekt auf
// topic_ok/needs_prompt gesetzt (2 vorherige Einmalig-Workflows), ein erneutes Leeren wuerde
// diesen Fortschritt zunichtemachen und unnoetig einen kompletten Agenten-Ketten-Rerun erzwingen.
return TARGETS.map(t => ({
  json: {
    vorgangKey: t.vorgangKey,
    vorgangsnummer: t.vorgangsnummer,
    contentStage: t.targetStage || 'needs_summary',
    contentErrorReason: '',
    last_error_code: '',
    last_error_message: '',
    last_error_stage: '',
    last_error_at: '',
    next_retry_at: '',
    retry_count: 0
  }
}));
